def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    weak_count = 0
    rich_aggressive = 0
    failed_yesterday = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                weak_count += 1
            if opp.get('budget', 0) > 600:
                if bid is not None and float(bid) >= 95:
                    rich_aggressive += 1
            if prev.get('status') not in (None, 'ok', 'alive', 'survived'):
                failed_yesterday += 1
            if prev.get('error'):
                failed_yesterday += 1

    if not alive:
        return float(min(budget, 1.0))

    max_prev = max(prev_bids) if prev_bids else 90.0
    min_prev = min(prev_bids) if prev_bids else 60.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 90.0

    expected_units = supply / float(WATER_REQ)
    abundant = expected_units >= 1.7
    tight = expected_units <= 1.25

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1
    if day >= 8:
        urgency += 1

    if urgency >= 5:
        bid = max_prev + 8.0
    elif urgency >= 3:
        bid = max(avg_prev + 3.0, 88.0)
    else:
        if abundant:
            bid = max(22.0, min_prev * 0.45)
        elif tight:
            bid = max(48.0, avg_prev * 0.62)
        else:
            bid = max(34.0, avg_prev * 0.52)

    if weak_count >= 2 and urgency <= 2:
        bid *= 0.82
    if rich_aggressive >= 2 and urgency <= 1:
        bid *= 0.9
    if failed_yesterday > 0 and urgency <= 2:
        bid *= 0.85

    if hp >= 8 and no_water_days == 0 and day <= 3:
        bid = min(bid, 46.0 if abundant else 58.0)

    reserve = DAILY_SALARY * max(0, 10 - day)
    safe_cap = budget - reserve * 0.18
    if urgency >= 3:
        safe_cap = budget - reserve * 0.08
    if safe_cap < 0:
        safe_cap = budget * 0.5

    bid = min(bid, budget, safe_cap)

    floor_bid = 0.0
    if urgency >= 5:
        floor_bid = min(95.0, budget)
    elif urgency >= 3:
        floor_bid = min(72.0, budget)
    elif tight:
        floor_bid = min(38.0, budget)
    else:
        floor_bid = min(20.0, budget)

    bid = max(floor_bid, bid)
    if bid < 0:
        bid = 0.0
    return float(round(min(bid, budget), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and yesterday bids
    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents, spend enough to cover requirement
    if not alive_opps:
        target = DAILY_SALARY * 0.45
        return float(min(my_status['budget'], target))

    # Immediate reaction from yesterday's previous_trace
    bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(bids) if bids else 0.0
    second_prev_bid = sorted(bids)[-2] if len(bids) >= 2 else 0.0

    # Estimate how many bidders likely push high: if someone bid very high yesterday, they may continue.
    # Use supply to decide aggressiveness: with higher supply, we can bid less and still win.
    supply_frac = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_frac = max(0.0, min(1.0, supply_frac))

    # Base bid: aim around a fraction of daily salary, adjusted by supply and yesterday pressure.
    if my_status['hp'] <= 2:
        base = DAILY_SALARY * 0.85
    elif my_status['hp'] <= 4:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * (0.55 - 0.15 * supply_frac)

    # If yesterday someone bid extremely high, we must be competitive but not suicidal.
    # Try to beat the second-highest if the highest was far above typical.
    typical_high = DAILY_SALARY * 0.9
    if highest_prev_bid >= typical_high:
        # Win-or-die pressure: bid slightly above second-highest (safer than matching highest)
        target = max(base, second_prev_bid + 2.0)
    elif highest_prev_bid >= DAILY_SALARY * 0.75:
        target = max(base, highest_prev_bid * 0.75)
    else:
        # Low pressure: bid enough to secure water while conserving budget
        target = max(base, DAILY_SALARY * (0.45 + 0.1 * supply_frac))

    # No-water days increases urgency
    no_water_days = int(my_status.get('no_water_days', 0))
    if no_water_days >= 3:
        target *= 1.25
    elif no_water_days == 2:
        target *= 1.10

    # Budget cap and safety
    budget = float(my_status['budget'])
    if budget <= 0:
        return 0.0

    # Avoid overbidding when budget is scarce
    # Keep at least a small buffer for later days if possible.
    buffer = DAILY_SALARY * 0.2
    max_affordable = max(0.0, budget - buffer)
    final_bid = min(float(target), max_affordable if max_affordable > 0 else budget)

    # Ensure non-negative and not exceeding budget
    if final_bid < 0:
        final_bid = 0.0
    if final_bid > budget:
        final_bid = budget

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    current_day = int(day_context['day'])

    alive_opponents = {aid: opp for aid, opp in opponents_status.items() if opp['alive']}

    max_prev_bid = 0.0
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if prev['bid'] > max_prev_bid:
                max_prev_bid = prev['bid']

    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    remaining_days = 10 - current_day + 1
    survival_budget_limit = budget / remaining_days if remaining_days > 0 else budget

    supply_factor = WATER_REQ / supply
    base_bid = min(survival_budget_limit, DAILY_SALARY * 0.5 * supply_factor)

    if no_water >= 1 or hp <= 2:
        desired = min(budget, DAILY_SALARY * 0.9)
    elif max_prev_bid > DAILY_SALARY * 0.7:
        if hp > 3:
            desired = min(budget, DAILY_SALARY * 0.4)
        else:
            desired = min(budget, max(base_bid, max_prev_bid + 1.0))
    else:
        desired = base_bid

    bid = max(0.0, min(budget, desired))
